# Assuming the following mock classes and methods for testing purposes

class MockPatient:
    def __init__(self, age, conditions, severities):
        self.age = age
        self._conditions = conditions
        self._severities = severities

    def get_total_conditions(self):
        return len(self._conditions)

    def get_average_severity(self):
        if not self._severities:
            return 0
        return sum(self._severities) / len(self._severities)

class MockHospital:
    def __init__(self, patient_dict, records_dict):
        self.patient_dict = patient_dict
        self.records_dict = records_dict

    def get_patient(self, patient_id):
        return self.patient_dict[patient_id]

    def get_recent_records(self, patient_id, days):
        # returns a list of dicts, each record is {"vitals": {"heart_rate": ..., ...}, ...}
        return self.records_dict.get(patient_id, [])

# Helper for "abnormal vitals": for testing, define a function that says any record in recent records with heart_rate > 100, or systolic > 140, diastolic > 90, etc counts as abnormal.
def contains_abnormal_vitals(records):
    for rec in records:
        heart_rate = rec.get('vitals', {}).get('heart_rate', 70)
        systolic = rec.get('vitals', {}).get('systolic', 120)
        diastolic = rec.get('vitals', {}).get('diastolic', 80)
        if heart_rate > 100 or systolic > 140 or diastolic > 90:
            return True
    return False

def patient_risk_score(hospital, patient_id):
    '''
    Calculate risk score using formula:
    (patient.age / 100 * 30) +
    (patient.get_total_conditions() * 5 * 25/100) +
    (patient.get_average_severity() * 10 * 25/100) +
    (20 if recent records have abnormal vitals else 0)
    Returns: float between 0.0 and 100.0.
    '''
    patient = hospital.get_patient(patient_id)
    age_score = (patient.age / 100.0) * 30
    conditions_score = (patient.get_total_conditions() * 5) * 0.25
    severity_score = (patient.get_average_severity() * 10) * 0.25
    records = hospital.get_recent_records(patient_id, 90)
    abnormal = contains_abnormal_vitals(records)
    abnormal_score = 20 if abnormal else 0
    score = age_score + conditions_score + severity_score + abnormal_score
    # Clamp between 0 and 100
    score = max(0.0, min(100.0, score))
    return score

