def calculate_simple_gpa(university, student_id):
    '''
    Calculates the simple cumulative GPA for a student given a university object and student_id.

    Args:
        university: University object with course, enrollment, student data
        student_id: ID of the student

    Returns:
        GPA as a float (0.0 to 4.0)
    '''
    total_points = 0.0
    total_credits = 0

    enrollments = university.get_student_enrollments(student_id)
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course is not None:
            grade_points = enrollment.get_grade_points()
            total_points += grade_points * course.credits
            total_credits += course.credits

    if total_credits == 0:
        return 0.0
    else:
        return total_points / total_credits


